css:
/* Sổ tay thuật ngữ — ledger tokens */
:root{
  --bg:#f5f1e8; --surface:#fdfbf5; --text:#1b1a16; --text-muted:#57534a; --text-soft:#6b6558;
  --accent:#a63f1c; --accent-soft:#f3e0d2; --border:#ddd5c4; --border-interactive:#8a8270; --band:#f1ede2;
  --basic:#2e5e3a; --basic-bg:#e3eee4;
  --inter:#8a5a0b; --inter-bg:#f5e9d2;
  --adv:#a63f1c; --adv-bg:#f6e2d8;
  --on-badge:#fff;
  --mark:#f3e0d2;
  --focus:#a63f1c;
  --toolbar-h:3.25rem;
  --serif:'Literata','Iowan Old Style',Palatino,Georgia,serif;
  --sans:'Be Vietnam Pro',system-ui,'Segoe UI',Roboto,sans-serif;
  --mono:'JetBrains Mono',ui-monospace,'SF Mono',Consolas,monospace;
  --measure:min(72ch,100%);
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#131311; --surface:#1c1b18; --text:#ede9e0; --text-muted:#a9a296; --text-soft:#9a9385;
    --accent:#f08a5d; --accent-soft:#3a241a; --border:#3a372f; --border-interactive:#6f6a5e; --band:#1a1913;
    --basic:#9bd1a4; --basic-bg:#1e2a20;
    --inter:#e5b866; --inter-bg:#2a2418;
    --adv:#f5a183; --adv-bg:#2e1d16;
    --on-badge:#131311;
    --mark:#3a241a;
    --focus:#f08a5d;
  }
}
:root[data-theme="dark"]{
  --bg:#131311; --surface:#1c1b18; --text:#ede9e0; --text-muted:#a9a296; --text-soft:#9a9385;
  --accent:#f08a5d; --accent-soft:#3a241a; --border:#3a372f; --border-interactive:#6f6a5e; --band:#1a1913;
  --basic:#9bd1a4; --basic-bg:#1e2a20;
  --inter:#e5b866; --inter-bg:#2a2418;
  --adv:#f5a183; --adv-bg:#2e1d16;
  --on-badge:#131311;
  --mark:#3a241a;
  --focus:#f08a5d;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--toolbar-h) + 12px);-webkit-text-size-adjust:100%}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:1.03125rem;line-height:1.65;overflow-wrap:break-word}
.visually-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip-link{position:absolute;left:-9999px;top:0;background:var(--text);color:var(--bg);padding:.6rem 1rem;z-index:60;font-family:var(--mono);font-size:.8rem}
.skip-link:focus{left:0}
a{color:var(--accent);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--text)}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
button,input,select{font:inherit;color:inherit}

/* masthead */
.masthead{background:var(--bg);border-bottom:1px solid var(--border)}
.masthead-inner{max-width:1560px;margin:0 auto;padding:clamp(1.75rem,4vw,3rem) clamp(16px,4vw,56px) 1.25rem}
.masthead-kicker{font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin:0 0 .5rem}
.masthead-title{font-family:var(--serif);font-weight:700;font-size:clamp(1.75rem,4.5vw,2.5rem);line-height:1.15;letter-spacing:-.01em;margin:0;max-width:22ch;text-wrap:balance}
.masthead-dek{font-size:1rem;color:var(--text-muted);max-width:58ch;margin:.75rem 0 0}
.masthead-dek strong{color:var(--text);font-weight:600}
.masthead-stats{font-family:var(--mono);font-size:.8125rem;color:var(--text-muted);margin:.85rem 0 0;letter-spacing:.01em}
.level-bar{display:flex;height:6px;margin:.85rem 0 0;max-width:420px;border:1px solid var(--border);border-radius:2px;overflow:hidden}
.level-bar span{display:block;height:100%}
.level-bar .lb-basic{background:var(--basic)}
.level-bar .lb-intermediate{background:var(--inter)}
.level-bar .lb-advanced{background:var(--adv)}
.level-legend{display:flex;flex-wrap:wrap;gap:.35rem 1rem;font-family:var(--mono);font-size:.75rem;color:var(--text-muted);margin:.45rem 0 0}
.level-legend .ll-basic{color:var(--basic)}
.level-legend .ll-inter{color:var(--inter)}
.level-legend .ll-adv{color:var(--adv)}

/* sticky toolbar */
.toolbar{position:sticky;top:0;z-index:40;background:var(--surface);border-bottom:1px solid var(--border)}
.toolbar-inner{max-width:1560px;margin:0 auto;padding:.55rem clamp(16px,4vw,56px);display:flex;flex-wrap:wrap;align-items:center;gap:.5rem .75rem}
.searchwrap{position:relative;flex:1 1 14rem;min-width:12rem}
#q{width:100%;font-family:var(--sans);font-size:.95rem;padding:.45rem .7rem;background:var(--bg);color:var(--text);border:1px solid var(--border-interactive);border-radius:3px}
#q::placeholder{color:var(--text-soft)}
#q:focus{border-color:var(--focus)}
.seg{display:inline-flex;border:1px solid var(--border-interactive);border-radius:3px;overflow:hidden;flex:0 0 auto}
.seg button{font-family:var(--mono);font-size:.72rem;letter-spacing:.02em;padding:.38rem .55rem;background:transparent;border:0;border-right:1px solid var(--border);color:var(--text-muted);cursor:pointer;white-space:nowrap}
.seg button:last-child{border-right:0}
.seg button:focus-visible{outline-offset:-3px}
.seg button:hover{color:var(--text);background:var(--band)}
.seg button[aria-pressed="true"]{background:var(--text);color:var(--bg)}
.seg button[data-filter-level="basic"][aria-pressed="true"]{background:var(--basic);color:var(--on-badge)}
.seg button[data-filter-level="intermediate"][aria-pressed="true"]{background:var(--inter);color:var(--on-badge)}
.seg button[data-filter-level="advanced"][aria-pressed="true"]{background:var(--adv);color:var(--on-badge)}
.dom-select{font-family:var(--mono);font-size:.72rem;padding:.38rem .45rem;background:var(--bg);color:var(--text);border:1px solid var(--border-interactive);border-radius:3px;max-width:14rem}
.live-count{font-family:var(--mono);font-size:.75rem;color:var(--text-muted);margin-left:auto;white-space:nowrap}
.theme-btn{font-family:var(--mono);font-size:.72rem;padding:.38rem .55rem;background:transparent;border:1px solid var(--border-interactive);border-radius:3px;cursor:pointer;color:var(--text-muted);flex:0 0 auto}
.theme-btn:hover{color:var(--text);border-color:var(--text-muted)}

/* body shell */
.shell{max-width:1560px;margin:0 auto;display:grid;grid-template-columns:1fr;gap:0;padding:0 clamp(16px,4vw,56px)}
@media (min-width:1024px){
  .shell{grid-template-columns:272px minmax(0,1fr);gap:48px}
}
.toc{font-size:.875rem;padding:0 0 1rem}
@media (min-width:1024px){
  .toc{position:sticky;top:var(--toolbar-h);align-self:start;max-height:calc(100vh - var(--toolbar-h));overflow-y:auto;border-right:1px solid var(--border);padding:1.25rem 1rem 2rem 0;margin-right:-1px}
}
@media (max-width:1023px){
  .toc{border-bottom:1px solid var(--border);margin:0 calc(-1 * clamp(16px,4vw,56px));padding:0 clamp(16px,4vw,56px)}
  .toc>summary{cursor:pointer;font-family:var(--mono);font-size:.75rem;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);padding:.75rem 0;list-style:none}
  .toc>summary::-webkit-details-marker{display:none}
  .toc>summary::after{content:' ▾';font-size:.7rem}
  .toc[open]>summary::after{content:' ▴'}
  .toc-body{padding-bottom:1rem}
}
@media (min-width:1024px){
  .toc>summary{display:none}
}
.toc-head{font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin:0 0 .6rem}
@media (max-width:1023px){.toc-head{display:none}}
.toc ul{list-style:none;margin:0;padding:0}
.toc li a{display:flex;justify-content:space-between;gap:.5rem;align-items:baseline;padding:.22rem .35rem .22rem .45rem;color:var(--text-muted);text-decoration:none;border-left:2px solid transparent}
.toc li a:hover{color:var(--text)}
.toc li a[aria-current="location"]{color:var(--text);border-left-color:var(--accent);font-weight:600}
.toc-part{margin-bottom:.85rem}
.toc-part>a{font-family:var(--serif);font-weight:600;font-size:.95rem;color:var(--text);padding-top:.45rem}
.toc-part-no{font-family:var(--mono);font-size:.6875rem;color:var(--text-muted);min-width:1.4em}
.toc-part-name{flex:1}
.toc-dom-name{flex:1}
.toc-count{font-family:var(--mono);font-size:.6875rem;color:var(--text-muted)}

.content{padding:1.5rem 0 4rem;min-width:0}

/* part band — the one oversized moment */
.part{margin-bottom:3.5rem}
.part-band{display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(1rem,3vw,2.5rem);align-items:end;background:var(--band);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:1.25rem clamp(.75rem,2vw,1.5rem);margin-bottom:2rem}
@media (min-width:1024px){
  .part-band{margin-left:-3rem}
}
.part-numeral{font-family:var(--serif);font-weight:700;font-size:clamp(72px,12vw,148px);line-height:.85;letter-spacing:-.03em;color:var(--text);opacity:.92;margin:0}
.part-meta{padding-bottom:.35rem;min-width:0}
.part-kicker{font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin:0 0 .25rem}
.part-title{font-family:var(--serif);font-weight:600;font-size:clamp(1.35rem,2.5vw,1.75rem);line-height:1.2;margin:0;text-wrap:balance}
.part-blurb{color:var(--text-muted);margin:.55rem 0 0;font-size:.95rem;max-width:52ch}
.part-stats{font-family:var(--mono);font-size:.75rem;color:var(--text-muted);margin:.45rem 0 0}

.domain{margin-bottom:2.25rem}
.domain[hidden]{display:none}
.domain-title{font-family:var(--sans);font-weight:600;font-size:1.125rem;letter-spacing:.01em;margin:0 0 .35rem;padding:.4rem 0;border-bottom:1px solid var(--border-interactive);display:flex;justify-content:space-between;align-items:baseline;gap:1rem;position:sticky;top:var(--toolbar-h);background:var(--bg);z-index:5}
.domain-count{font-family:var(--mono);font-weight:400;font-size:.75rem;color:var(--text-muted)}

/* entry — ledger row */
.entry{display:grid;grid-template-columns:minmax(0,1fr);column-gap:20px;padding:1.1rem 0;border-bottom:1px solid var(--border);position:relative}
.entry[hidden]{display:none}
@media (min-width:720px){
  .entry{grid-template-columns:64px minmax(0,1fr)}
  .entry-gutter{grid-column:1;grid-row:1 / -1}
  .entry-main{grid-column:2}
}
@media (min-width:1400px){
  .entry{grid-template-columns:64px minmax(0,1fr) 200px}
}
.entry-gutter{font-family:var(--mono);font-size:.72rem;color:var(--text-muted);padding-top:.2rem;display:flex;flex-direction:row;gap:.5rem;align-items:baseline;flex-wrap:wrap;margin-bottom:.25rem}
@media (min-width:720px){
  .entry-gutter{flex-direction:column;gap:.35rem;margin-bottom:0}
}
.entry-no{font-variant-numeric:tabular-nums}
.entry:hover{background:var(--surface)}
.entry:hover .entry-no{color:var(--accent)}
.entry-lvl{font-weight:700;letter-spacing:.04em}
.entry[data-level="basic"] .entry-lvl{color:var(--basic)}
.entry[data-level="intermediate"] .entry-lvl{color:var(--inter)}
.entry[data-level="advanced"] .entry-lvl{color:var(--adv)}
.entry-main{grid-column:1;min-width:0}
@media (min-width:720px){
  .entry-main{grid-column:2}
}
.entry-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:.5rem .75rem;margin:0}
.entry-term{font-family:var(--serif);font-weight:600;font-size:1.25rem;line-height:1.45;margin:0;text-wrap:balance;letter-spacing:-.01em;min-width:0;overflow-wrap:anywhere}
.entry-term mark,.entry-aliases mark{background:var(--mark);color:var(--text);padding:0 .1em;border-radius:1px}
.permalink{font-family:var(--mono);font-size:.7rem;color:var(--text-muted);background:transparent;border:1px solid transparent;border-radius:2px;padding:.1rem .3rem;cursor:pointer;opacity:0;flex:0 0 auto}
.entry:hover .permalink,.permalink:focus-visible{opacity:1;border-color:var(--border-interactive)}
.permalink:hover{color:var(--accent)}
.permalink.is-ok{opacity:1;color:var(--accent)}
.entry-domain{display:none;font-family:var(--mono);font-size:.6875rem;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin:.15rem 0 0;width:100%}
body.is-filtered .entry-domain{display:block}
.entry-aliases{font-family:var(--mono);font-size:.8125rem;color:var(--text-muted);margin:.2rem 0 0;line-height:1.5}
.entry-aliases .lbl{font-size:.6875rem;letter-spacing:.06em;text-transform:uppercase;margin-right:.35rem}
.entry-block{margin:.65rem 0 0;font-size:1.03125rem;line-height:1.65;text-wrap:pretty;max-width:var(--measure)}
.entry-block .lbl{display:block;font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin-bottom:.15rem;font-weight:500}
.entry-origin{margin:.7rem 0 0;font-family:var(--serif);font-style:italic;font-size:.95rem;line-height:1.55;color:var(--text-muted);border-left:2px solid var(--accent-soft);padding-left:.85rem;max-width:var(--measure)}
.entry-origin .lbl{font-family:var(--mono);font-style:normal;font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);margin-bottom:.15rem;display:block;font-weight:500}
@media (min-width:1400px){
  .entry-origin{position:absolute;top:1.1rem;right:0;width:200px;border-left:0;border-top:1px solid var(--border);padding:.35rem 0 0;margin:0;max-width:none;font-size:.875rem}
}
.entry-related{font-family:var(--mono);font-size:.8125rem;color:var(--text-muted);margin:.7rem 0 0;line-height:1.55;max-width:var(--measure)}
.entry-related .lbl{font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;margin-right:.35rem}
.entry-related a{color:var(--accent);text-decoration-style:dotted;text-underline-offset:3px}
.entry-related a:hover{color:var(--text);text-decoration-style:solid}
.rel-plain{color:var(--text-soft);border-bottom:1px dashed var(--border-interactive)}
.entry:target{background:var(--accent-soft);box-shadow:inset 4px 0 0 var(--accent)}
@media (prefers-reduced-motion:reduce){
  .entry:target{background:transparent;box-shadow:inset 4px 0 0 var(--accent)}
}
.entry.flash{animation:flash 1.4s ease-out}
@keyframes flash{0%{background:var(--accent-soft)}100%{background:transparent}}
@media (prefers-reduced-motion:reduce){.entry.flash{animation:none;outline:2px solid var(--focus);outline-offset:2px}}

/* empty state */
.empty-state{padding:2.5rem 0;max-width:40ch}
.empty-state[hidden]{display:none}
.empty-state p{color:var(--text-muted);margin:0 0 .85rem}
.reset-btn{font-family:var(--mono);font-size:.8rem;padding:.45rem .9rem;background:transparent;color:var(--text);border:1px solid var(--border-interactive);border-radius:3px;cursor:pointer}
.reset-btn:hover{border-color:var(--accent);color:var(--accent)}

/* footer + to-top */
.colophon{border-top:1px solid var(--border);margin-top:1rem}
.colophon p{max-width:1560px;margin:0 auto;padding:1.1rem clamp(16px,4vw,56px);font-family:var(--mono);font-size:.75rem;color:var(--text-muted)}
.to-top-wrap{position:fixed;right:1rem;bottom:1rem;z-index:40}
.to-top{width:42px;height:42px;border-radius:3px;border:1px solid var(--border-interactive);background:var(--surface);color:var(--text);font-size:1rem;cursor:pointer;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s,visibility .2s}
.to-top.is-visible{opacity:1;visibility:visible;pointer-events:auto}
.to-top:hover{border-color:var(--accent);color:var(--accent)}
@media (prefers-reduced-motion:reduce){.to-top{transition:none}}

/* narrow toolbar: 3 rows instead of 5 — search+theme / seg / select+count */
@media (max-width:720px){
  .toolbar-inner{padding:.45rem clamp(16px,4vw,56px);row-gap:.5rem}
  .searchwrap{order:1;flex:1 1 10rem;min-width:8rem}
  .theme-btn{order:5;margin-left:0}
  .seg{order:3;flex:1 1 100%;justify-content:center;flex-wrap:wrap}
  .seg button{flex:1 1 auto;padding:.42rem .3rem;font-size:.68rem}
  .dom-select{order:4;flex:1 1 8rem;min-width:6rem;max-width:none}
  .live-count{order:5;margin-left:0;flex:0 1 auto;text-align:right}
  .lc-pre,.lc-post{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
  .part-band{margin-left:0}
}


/* interview section */
.interview{border-top:1px solid var(--border);margin-top:3rem;padding-top:.5rem;scroll-margin-top:calc(var(--toolbar-h) + 12px)}
.iv-head{background:var(--band);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:1.1rem clamp(.75rem,2vw,1.5rem);margin-bottom:2rem}
.iv-kicker{font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted);margin:0 0 .3rem}
.iv-title{font-family:var(--serif);font-weight:600;font-size:clamp(1.35rem,2.5vw,1.75rem);line-height:1.2;margin:0;text-wrap:balance}
.iv-intro{color:var(--text-muted);margin:.55rem 0 0;font-size:.95rem;max-width:64ch}
.iv-stats{font-family:var(--mono);font-size:.75rem;color:var(--text-muted);margin:.45rem 0 0}
.iv-cat{margin-bottom:2.5rem}
.iv-cat-title{font-family:var(--sans);font-weight:600;font-size:1.125rem;letter-spacing:.01em;margin:0 0 .35rem;padding:.4rem 0;border-bottom:1px solid var(--border-interactive);display:flex;justify-content:space-between;align-items:baseline;gap:1rem}
.iv-cat-count{font-family:var(--mono);font-weight:400;font-size:.75rem;color:var(--text-muted)}
.iv-cat-intro{color:var(--text-muted);font-size:.95rem;max-width:var(--measure);margin:.5rem 0 .9rem}
.iv-q{padding:1.15rem 0;border-bottom:1px solid var(--border);max-width:min(78ch,100%)}
.iv-qs{margin:.35rem 0 0;padding-left:1.5rem}
.iv-qs>li::marker{font-family:var(--mono);font-size:.8em;color:var(--text-muted)}
.iv-scenario{font-family:var(--serif);font-style:italic;font-size:1rem;line-height:1.6;color:var(--text-muted);border-left:2px solid var(--accent-soft);padding-left:.85rem;margin:0 0 .7rem}
.iv-ask{font-family:var(--serif);font-weight:600;font-size:1.15rem;line-height:1.45;margin:0 0 .6rem;text-wrap:balance}
.iv-steps{margin:.2rem 0 0;padding-left:1.35rem;font-size:.98rem;line-height:1.6;max-width:var(--measure)}
.iv-steps li{margin:.28rem 0}
.iv-steps li::marker{font-family:var(--mono);font-size:.8em;color:var(--text-muted)}
.iv-terms{font-family:var(--mono);font-size:.8125rem;color:var(--text-muted);margin:.75rem 0 0;line-height:1.7;max-width:var(--measure)}
.iv-terms .lbl{font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;margin-right:.35rem}
.iv-terms a{color:var(--accent);text-decoration-style:dotted;text-underline-offset:3px}
.iv-terms a:hover{color:var(--text);text-decoration-style:solid}
.iv-terms .rel-plain{color:var(--text-soft);border-bottom:1px dashed var(--border-interactive)}
.iv-signals{display:grid;gap:.4rem .75rem;margin:.75rem 0 0;font-size:.95rem;max-width:var(--measure)}
@media (min-width:720px){.iv-signals{grid-template-columns:1fr 1fr}}
.iv-signal{margin:0;line-height:1.55}
.iv-signal .lbl{display:block;font-family:var(--mono);font-size:.6875rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:.1rem;font-weight:500}
.iv-signal.good .lbl{color:var(--basic)}
.iv-signal.bad .lbl{color:var(--adv)}
.toc-interview{margin-top:.9rem;padding-top:.7rem;border-top:1px solid var(--border)}
.toc-interview>a{font-family:var(--serif);font-weight:600;font-size:.95rem;color:var(--text)}
